--This is the SQL for setting up a student field computed field that calculates to Y when a student has been scheduled with an OOF teacher 


WITH ESE AS ( SELECT esel.source_id AS student_id, exc.code AS exc FROM custom_field_log_entries esel JOIN custom_field_select_options exc ON esel.log_field3 = exc.id::varchar JOIN custom_field_select_options sts ON esel.log_field6 = sts.id::varchar JOIN custom_fields cf ON cf.id = esel.field_id AND cf.column_name = 'custom_890' WHERE esel.log_field4 = 'Y' AND sts.code = 'A' ), sched AS ( SELECT sc.student_id, JSON_ARRAY_ELEMENTS(cp.out_reason::JSON)::TEXT AS reason, sc.custom_22 AS tier FROM schedule sc JOIN student_enrollment se ON se.student_id = sc.student_id AND se.syear = sc.syear AND ( (CAST(CURRENT_DATE AS date) BETWEEN se.start_date AND se.end_date) OR (CAST(CURRENT_DATE AS date) >= se.start_date AND se.end_date IS NULL) ) JOIN course_periods cp ON cp.course_period_id = sc.course_period_id JOIN courses c ON c.course_id = cp.course_id WHERE sc.syear = {SYEAR} AND sc.student_id = {STUDENT_ID} AND COALESCE(cp.out_reason, '') <> '' AND ( (CAST(CURRENT_DATE AS date) BETWEEN sc.start_date AND sc.end_date) OR (CAST(CURRENT_DATE AS date) >= se.start_date AND sc.end_date IS NULL) ) AND (cp.custom_28 IN ('O', 'B') or (cp.custom_28 = 'N' and c.short_name !~ '^[A-Za-z]{3}[A-Za-z0-9][0-9]{3}')) AND cp.CP_CHECKBOX_SETTING_5 IS DISTINCT FROM 'Y' AND EXISTS ( SELECT '' FROM marking_periods mp WHERE ( mp.marking_period_id = sc.marking_period_id OR (sc.marking_period_id = 0 AND mp.type = 'year') ) AND mp.syear = {SYEAR} AND mp.school_id = sc.school_id AND mp.start_date <= CAST(CURRENT_DATE AS date) AND mp.end_date >= CAST(CURRENT_DATE AS date) ) ) SELECT DISTINCT s.student_id, 'Y' AS value FROM students s JOIN sched sc ON sc.student_id = s.student_id LEFT JOIN custom_field_select_options ell ON s.custom_626 = ell.id AND ell.source_class = 'CustomField' LEFT JOIN ese ON sc.student_id = ese.student_id WHERE s.student_id = {STUDENT_ID} AND ( sc.reason IN ('"SUB"', '"COMBINED"', '"CER"', '"ASD"', '"GRADE"') OR (sc.reason = '"ELL"' AND ell.code = 'LY') OR (sc.reason = '"ESE"' AND COALESCE(ese.exc, '') NOT IN ('L', '')) OR (sc.reason = '"GIFT"' AND COALESCE(ese.exc, '') = 'L') OR (sc.reason = '"REA"' AND sc.tier IN ('A', 'B')) )